bounded_host_request.command:
set -eu
docker inspect --format '{{.Config.Image}} {{.State.Running}} {{.RestartCount}}' gace-createvdobot-videobot-poll-1
docker exec -i gace-createvdobot-videobot-poll-1 node --input-type=module <<'NODE'
import {mkdtemp,readFile,rm,stat} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {createHash} from 'node:crypto';
import {prepareMissingPreviewAssets} from '/opt/videobot/src/sales/autoPreview.mjs';
import {planAutomaticSample} from '/opt/videobot/src/sales/sampleMedia.mjs';
const run=promisify(execFile),root=await mkdtemp(join(tmpdir(),'synthetic-preview-'));
const hash=b=>createHash('sha256').update(b).digest('hex');
try {
 const input=join(root,'synthetic.mp4'),a=join(root,'a.jpg'),b=join(root,'b.jpg'),out=join(root,'sample.mp4');
 await run('ffmpeg',['-nostdin','-v','error','-f','lavfi','-i','testsrc2=size=160x90:rate=10','-t','120','-c:v','libx264','-threads','1','-pix_fmt','yuv420p',input],{timeout:90000});
 const original=hash(await readFile(input));
 const result=await prepareMissingPreviewAssets({sourcePath:input,thumbnailOutputPath:a,secondThumbnailOutputPath:b,sampleOutputPath:out});
 const media=await readFile(out),first=await readFile(a),second=await readFile(b);
 const {stdout}=await run('ffprobe',['-v','error','-show_entries','format=duration:stream=codec_name','-of','json',out]);
 const evidence={plan:planAutomaticSample(120),duration:result.sample.durationSeconds,thumbnailCount:2,distinctImages:hash(first)!==hash(second),size:media.length,fastStart:media.indexOf('moov')>0&&media.indexOf('moov')<media.indexOf('mdat'),sourceUnchanged:original===hash(await readFile(input)),probe:JSON.parse(stdout)};
 console.log(JSON.stringify(evidence));
 if(Math.abs(evidence.duration-60)>0.15||!evidence.distinctImages||!evidence.fastStart||!evidence.sourceUnchanged||media.length>20000000)throw Error('synthetic preview verification failed');
} finally {await rm(root,{recursive:true,force:true});}
NODE
